{
  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C10","C08","C26","C61","C54","C55","C59","C63","C66","C67","C70","C71","C80","C90","C97","C57","C64","C137","C116","C107","C130"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C10","C08","C26","C137","C116","C107","C130"],
  "claims": [
    {
      "claim": "The query is a phosphinic-ester ACE-inhibitor prodrug (fosinopril-like); the most class-relevant L1 record, perindopril in fasted healthy/hypertensive subjects, reports absolute oral bioavailability of 66–95%, well above the 20% threshold.",
      "card_ids": ["C10"]
    },
    {
      "claim": "Perindoprilat after oral perindopril in cirrhotic patients retained 30±6% bioavailability, indicating ACE-inhibitor prodrug/active exposure remains above threshold even with hepatic impairment.",
      "card_ids": ["C08","C26"]
    },
    {
      "claim": "L3 oral exposure records for enalapril/enalaprilat and perindopril/perindoprilat show systemic Cmax/AUC after oral prodrug dosing, consistent with meaningful oral absorption and systemic exposure.",
      "card_ids": ["C66","C70","C80","C90","C71","C67","C97","C57","C64","C61","C54","C55","C59","C63"]
    },
    {
      "claim": "L4 enalapril prodrug permeability records show Papp ~1.93×10−6 cm/s in human iPS intestinal cells with reported Fa 0.60 (C137), and Papp 0.72–1.94×10−6 cm/s in Caco-2 (C116, C107), supporting that ACE-inhibitor ester prodrugs can be absorbed; SQ-29852, a phosphinic-acid ACE inhibitor, had 60% human absorption despite low Caco-2 Papp (C130).",
      "card_ids": ["C137","C116","C107","C130"]
    },
    {
      "claim": "Low permeability records for enalaprilat and lisinopril (C138, C126, C132, C125, C146, C141, C127) apply to active diacid ACE inhibitors, not to the ester prodrug query, and do not provide affirmative evidence for F<20%.",
      "card_ids": ["C138","C126","C132","C125","C146","C141","C127"]
    },
    {
      "claim": "Low-F records for sofosbuvir, saquinavir, PSI-6130, and other unrelated classes are not transferable and do not provide affirmative evidence for F<20%.",
      "card_ids": ["C22","C27","C29","C39","C40"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C137","C116","C107","C130"]
    }
  ],
  "evidence_gaps": [
    "No direct fosinopril-specific oral bioavailability, permeability, or solubility record is supplied; decision relies on structural/class analogy to perindopril and enalapril.",
    "L4 records are for other ACE inhibitors and unrelated molecules; enalapril prodrug permeability and SQ-29852 human absorption are the most relevant but not direct query measurements.",
    "Low permeability of active diacid ACE inhibitors (enalaprilat, lisinopril) is not transferable to the ester prodrug query.",
    "The query has no specified external condition, so cirrhosis-specific records may not transfer directly to a general population.",
    "Physicochemical prior indicates high molecular weight/TPSA and full ionization at pH 7.4, but no direct fosinopril solubility or permeability measurement is available."
  ],
  "decision_summary": "Predicted high (F≥20%) because the most transferable L1 evidence—perindopril and perindoprilat ACE-inhibitor prodrug/active records—shows oral bioavailability of 30–95%, all above threshold; L3 adds consistent oral exposure records for enalapril and perindopril prodrugs; L4 adds enalapril prodrug permeability (Fa 0.60) and SQ-29852 human absorption supporting the absorption component, while low permeability records for active diacid ACE inhibitors are not applicable to the prodrug query; no transferable affirmative evidence of F<20% appears."
}

